import 'package:benchmark_harness/benchmark_harness.dart';
import 'package:cell_flow/cell_flow.dart';

class DeferFutureBench extends AsyncBenchmarkBase {
  DeferFutureBench() : super('flow: deferFuture');
  late final FlowHandle h =
      Flow.deferFuture<int>(Cell.ingress<int>().cell, create: (_) async => 1);

  @override
  Future<void> run() async {
    for (var i = 0; i < 200; i++) {
      h.emit(i);
    }
    await Future<void>.delayed(const Duration(milliseconds: 50));
  }
}

class FromFutureOneShot extends AsyncBenchmarkBase {
  FromFutureOneShot() : super('flow: fromFuture');

  @override
  Future<void> run() async {
    for (var i = 0; i < 200; i++) {
      Flow.fromFuture<int>(Cell.ingress<int>().cell, future: Future.value(1));
    }
    await Future<void>.delayed(const Duration(milliseconds: 50));
  }
}

class FromFutureError extends AsyncBenchmarkBase {
  FromFutureError() : super('flow: fromFuture error');

  @override
  Future<void> run() async {
    for (var i = 0; i < 200; i++) {
      // Triggered + handled: measures the rejection path without an
      // unhandled zone error.
      final h = Flow.fromFuture<int>(Cell.ingress<int>().cell,
          future: Future<int>.error(StateError('x')).catchError((_) => -1),
          onError: (e, _) {});
      h.emit(0);
    }
    await Future<void>.delayed(const Duration(milliseconds: 20));
  }
}

